      "source": "rga",
      "articleId": "a88",
      "paragraph": "Ponen fin a la vía administrativa de conformidad con el artículo 114 de la Ley 39/2015: a) Los actos y las resoluciones administrativas del Presidente de la Ciudad Autónoma, denominados “Decretos”. b) Los actos y resoluciones administrativas del Consejo de Gobierno de la Ciudad Autónoma, denominados “Acuerdos”. c) Los actos resolutorios de un recurso de alzada, cualquiera que sea el órgano que los resuelva. d) Los actos y resoluciones administrativas del Pleno de la Asamblea, cuando ejercite las competencias a tenor del artículo 12.2 del Estatuto de Autonomía, los de la Mesa de la Asamblea, en su caso, o los del Consejo de Gobierno cuando resuelva por delegación de la Asamblea. e) Los actos y resoluciones de los miembros de la Asamblea y de otros órganos cuando actúen por delegación del Presidente. f) Los acuerdos, pactos, convenios o contratos que tengan la consideración de finalizadores del procedimiento. g) La resolución de los procedimientos complementarios en materia sancionadora a los que se refiere el artículo 90.4 de la Ley 39/2015. h) Las demás resoluciones de órganos, organismos y autoridades cuando una disposición legal o reglamentaria así lo establezca.",
